function localTargetPrice35DImpl(v,t,k,w){const base=BASE_PRICE[k],caps=NS.V06.capsForTile(t),stock=Number(t.stocks?.[k]||0),cap=Math.max(1,Number(caps?.[k]||1)),ratio=stock/cap,people=v?.tileResidents?.(t.id)?.filter(p=>p.alive)||[],pop=people.length,day=w.ordinalDay();let pressure=0;const e30=t.v30Economy||{},ledger=Array.isArray(e30.productionDaily)?e30.productionDaily:[],totals35D=(()=>{let s30=0,s120=0;for(const r of ledger){const d=Number(r.day);if(d>=day-29&&d<=day)s30+=Number(r[k]||0);if(d>=day-119&&d<=day)s120+=Number(r[k]||0);}return [s30,s120];})(),prod30=totals35D[0]/Math.max(1,Math.min(30,day)),prod120=totals35D[1]/Math.max(1,Math.min(120,day)),hasProd=ledger.length>0,flow=Number(t.marketState?.tradeVolume?.[k]||0),netFlow=Number(e30.flowOut?.[k]||0)-Number(e30.flowIn?.[k]||0);
 if(k==='food'){const daily=Math.max(.12,people.reduce((a,p)=>a+(Number(p.age)<15?.30:.42),0)),days=stock/daily;pressure=clamp((45-days)/32,-.65,1.75);if(hasProd){const supply=(prod30*.65+prod120*.35)/daily;pressure+=clamp((1-supply)*.16,-.16,.24);}pressure-=clamp((t.ratio?.('food',day)||0)*.12,0,.12);pressure+=clamp(netFlow/55,-.16,.16);}else{const project=localConstructionNeed(v,t,k),builtCap=(t.buildings||[]).reduce((a,b)=>a+(NS.BUILDINGS[b]?.capacity||0)*(t.buildingEfficiency?.(b)||1),0),shortage=Math.max(0,pop-builtCap),latent=shortage*(k==='wood'?3.0:2.0),maint=(t.buildings||[]).reduce((a,b)=>a+Number(NS.V09?.MAINT_BASE?.[b]?.[k]||0)*.005,0),baseline=pop*(k==='wood'?.18:.11)+6,expected=Math.max(6,project+latent+maint+baseline),coverage=stock/expected;pressure=clamp((1.35-coverage)/1.15,-.70,1.75);pressure+=clamp((project+latent)/Math.max(10,expected)*.58,0,.58);if(hasProd){const monthly=(prod30*.7+prod120*.3)*30;pressure-=clamp(monthly/Math.max(8,expected)*.34,0,.42);}pressure-=clamp((t.ratio?.(k,day)||0)*.14,0,.14);pressure+=clamp(netFlow/45,-.20,.20);}pressure+=clamp(flow/120,0,.16);const raw=clamp(base*(1+pressure*.72),base*.38,base*3.4),age=Number(w?.ordinalDay?.()||0);if(k==='wood'||k==='stone'){const anchor=k==='wood'?.35:.49;if(age<=120)return anchor;if(age<360){const z=(age-120)/240;return anchor+(raw-anchor)*z;}}return raw;}
