NS.Village.prototype.startLandDevelopment=function(w,tileId,reason='SPACE_PRESSURE'){const t=w.map.get(tileId);if(!t||t.ownerId!==this.id||t.terrain==='water'||landProjects(this).some(p=>p.tileId===tileId)||projectBusy(this,tileId))return false;ensureSpace(t);const pot=accessiblePotential(this,t);if(t.developedBuildSpace+.05>=pot)return false;const d=profile(t).diff,next=Math.min(pot,t.developedBuildSpace+2),gain=next-t.developedBuildSpace,cost={wood:+(8*d).toFixed(1),stone:+(6*d).toFixed(1),gold:+(4*d).toFixed(1)};if(!this.payBuild?.(tileId,cost))return false;const duration=Math.round(90*d*(this.hasTech('ENGINEERING')?.82:1)*(this.hasTech('URBAN_REDEVELOPMENT')?.86:1)),p={id:`ld-${this.id}-${w.ordinalDay()}-${Math.random().toString(36).slice(2,6)}`,tileId,startDay:w.ordinalDay(),progress:0,duration,cost,gain,reason};landProjects(this).push(p);w.log(`${this.name}이(가) (${t.x},${t.y})의 토지 정비를 시작했습니다.`,false,'LAND_DEVELOPMENT_STARTED',{village:this.name,tileId,gain:+gain.toFixed(1),from:+t.developedBuildSpace.toFixed(1),to:+next.toFixed(1),potential:+pot.toFixed(1),cost,duration,reason});return true;};
function progressLandDevelopment(v,w){const arr=landProjects(v);for(let i=arr.length-1;i>=0;i--){const p=arr[i],t=w.map.get(p.tileId);if(!t||t.ownerId!==v.id){arr.splice(i,1);continue;}const workers=v.tileResidents(p.tileId).filter(x=>x.alive&&x.age>=16&&x.assignment!=='PIONEER');if(!workers.length){p._v35gFirstSeenCal=p._v35gFirstSeenCal??Number(w.calendarOrdinalDay?.()||0);NS.V035G?.landCycle?.(v,w,p,'NO_LOCAL_WORKERS');continue;}const avg=workers.reduce((s,x)=>s+(x.skills?.building||0),0)/workers.length;p.progress+=clamp(.35+workers.length*.09+avg/450,.3,1.25);p._v35gFirstSeenCal=p._v35gFirstSeenCal??Number(w.calendarOrdinalDay?.()||0);NS.V035G?.landCycle?.(v,w,p,'PROGRESSED');if(p.progress>=p.duration){ensureSpace(t);const before=t.developedBuildSpace;t.developedBuildSpace=Math.min(accessiblePotential(v,t),t.developedBuildSpace+p.gain);arr.splice(i,1);w.log(`${v.name}의 (${t.x},${t.y}) 토지 정비가 완료되어 건축 가능 공간이 ${before.toFixed(1)} → ${t.developedBuildSpace.toFixed(1)}로 늘었습니다.`,false,'LAND_DEVELOPMENT_COMPLETED',{village:v.name,tileId:p.tileId,before:+before.toFixed(1),after:+t.developedBuildSpace.toFixed(1),potential:+accessiblePotential(v,t).toFixed(1)});}}}

/* ---------- actual building replacement projects ---------- */
function nextHousing(v,type){if(type==='house'&&v.hasTech('URBAN_PLANNING'))return'row_house';if(type==='row_house'&&v.hasTech('URBANIZATION'))return'collective_house';return null;}
const UPGRADE={row_house:{wood:24,stone:15,gold:7,duration:150},collective_house:{wood:36,stone:26,gold:16,duration:220}};
NS.Village.prototype.startHousingUpgrade=function(w,tileId,index,reason='HOUSING_DENSITY'){const t=w.map.get(tileId);if(!t||t.ownerId!==this.id||projectBusy(this,tileId))return false;const from=t.buildings?.[index],to=nextHousing(this,from);if(!to)return false;const extra=Math.max(0,buildingFootprint(to)-buildingFootprint(from));if(remainingSpace(this,t)+1e-6<extra)return false;const spec=UPGRADE[to],cost={wood:spec.wood,stone:spec.stone,gold:spec.gold};if(this.hasTech('ARCHITECTURE')){cost.wood*=.9;cost.stone*=.9;}if(!this.payBuild?.(tileId,cost))return false;const p={id:`up-${this.id}-${w.ordinalDay()}-${Math.random().toString(36).slice(2,6)}`,tileId,index,from,to,startDay:w.ordinalDay(),progress:0,duration:spec.duration,cost,reason};upgradeProjects(this).push(p);w.log(`${this.name}이(가) (${t.x},${t.y})의 ${NS.BUILDINGS[from]?.label||from}을(를) ${NS.BUILDINGS[to].label}(으)로 개축하기 시작했습니다.`,false,'BUILDING_UPGRADE_STARTED',{village:this.name,tileId,index,from,to,duration:p.duration,cost,reason});return true;};
