 // 2) replace an older dwelling when density pressure is high
 for(const x of rank){if(x.p.housing<68||projectBusy(this,x.t.id))continue;for(let i=0;i<x.t.buildings.length;i++){if(nextHousing(this,x.t.buildings[i])&&this.startHousingUpgrade(w,x.t.id,i,'HOUSING_DENSITY')){addV17Marker(this,w,x.t.id);return true;}}}
